//! Per-model list prices — the *only* source of cost figures.
//!
//! Two layers, both local: the snapshot `assets/prices.json` compiled into
//! the binary (regenerated by `tools/update-prices.py` from LiteLLM and
//! models.dev at pinned commits — see that script for what is taken and
//! why), and the user's own `<config>/tickover/prices.toml`, which wins
//! for any id it names. Nothing is fetched at run time; a price change
//! reaches the app as a reviewed diff to the snapshot, never silently.
//!
//! A model neither layer knows prices as `None` — rendered `—` — rather
//! than being estimated at a neighbour's rate. The lookup is exact after a
//! fixed normalisation ([`canonical`], [`price_for`]); there is no prefix
//! fallback, because a prefix is how `gpt-5.6-sol` once priced at
//! `gpt-5`'s rate and `claude-opus-4-8` at three times its own.
//!
//! Figures are USD per 1M tokens at public API list price; subscription
//! seats are never list-priced, so every cost this produces is an
//! "API-equivalent", not anyone's bill. Prices apply at query time to the
//! whole history, so a snapshot update re-prices the past too — which is
//! why [`sources_note`] names the snapshot date wherever costs are shown.
//!
//! Thinking tokens bill as output. A class the source gave no rate for
//! prices at the input rate (resolved in the snapshot itself).

use std::collections::BTreeMap;
use std::sync::{Arc, LazyLock, Mutex};
use std::time::{Duration, Instant};

use serde::Deserialize;

use crate::history::query::Totals;

/// USD per 1M tokens per class. `thinking` is priced at the output rate —
/// every provider that exposes it bills it that way.
#[derive(Debug, Clone, Copy, PartialEq, Deserialize)]
struct Price {
    #[serde(rename = "in")]
    input: f64,
    #[serde(rename = "out")]
    output: f64,
    #[serde(rename = "cr")]
    cache_read: f64,
    #[serde(rename = "cw")]
    cache_write: f64,
}

#[derive(Deserialize)]
struct Snapshot {
    snapshot: String,
    litellm: String,
    models_dev: String,
    models: BTreeMap<String, Price>,
}

static SNAPSHOT: LazyLock<Snapshot> = LazyLock::new(|| {
    serde_json::from_str(include_str!("../../assets/prices.json"))
        .expect("assets/prices.json is generated by tools/update-prices.py")
});

/// One entry of `prices.toml`, USD per 1M tokens. Cache rates are
/// optional and default to the input rate, the same rule the snapshot
/// applies to a class its source left blank.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct OverrideEntry {
    input: f64,
    output: f64,
    cache_read: Option<f64>,
    cache_write: Option<f64>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct OverrideFile {
    #[serde(default)]
    models: BTreeMap<String, OverrideEntry>,
}

/// The user's overrides, or why the file was set aside. An invalid file
/// is ignored *whole* — half-applying it would mix the user's prices with
/// the snapshot's in a way neither of them chose — and the reason is kept
/// for [`sources_note`], so the report says so instead of the edit simply
/// not working.
struct Overrides {
    models: BTreeMap<String, Price>,
    error: Option<String>,
}

const OVERRIDES_FILE: &str = "prices.toml";

/// How often a lookup may look at `prices.toml` again. The tray process
/// lives for days, so an edit has to land without a restart; a cached copy
/// a couple of seconds old costs nothing, a read per priced row would.
const OVERRIDES_RECHECK: Duration = Duration::from_secs(2);

struct OverridesCache {
    checked: Instant,
    /// The file's text as last read, `None` when it could not be. Compared
    /// whole rather than by mtime and size: a restored backup can carry
    /// both unchanged and still hold different prices.
    text: Option<Result<String, String>>,
    data: Arc<Overrides>,
}

static OVERRIDES: Mutex<Option<OverridesCache>> = Mutex::new(None);

fn no_overrides() -> Overrides {
    Overrides {
        models: BTreeMap::new(),
        error: None,
    }
}

/// The current overrides, re-read when the file's text changes.
fn overrides() -> Arc<Overrides> {
    // Unit tests never read the real config directory. Integration tests
    // under `tests/` are another crate and do get here: they run under a
    // substituted HOME like everything else that touches `<config>`.
    if cfg!(test) {
        return Arc::new(no_overrides());
    }
    let Some(path) = crate::plugin::app_config_dir().map(|d| d.join(OVERRIDES_FILE)) else {
        return Arc::new(no_overrides());
    };
    let mut cache = OVERRIDES.lock().unwrap_or_else(|e| e.into_inner());
    if let Some(c) = cache.as_ref() {
        if c.checked.elapsed() < OVERRIDES_RECHECK {
            return Arc::clone(&c.data);
        }
    }
    let text = read_text(&path);
    if let Some(c) = cache.as_mut() {
        if c.text == text {
            c.checked = Instant::now();
            return Arc::clone(&c.data);
        }
    }
    let data = Arc::new(match &text {
        None => no_overrides(),
        Some(Err(e)) => Overrides {
            models: BTreeMap::new(),
            error: Some(e.clone()),
        },
        Some(Ok(t)) => parse_overrides(t).unwrap_or_else(|e| Overrides {
            models: BTreeMap::new(),
            error: Some(e),
        }),
    });
    *cache = Some(OverridesCache {
        checked: Instant::now(),
        text,
        data: Arc::clone(&data),
    });
    data
}

/// A missing file is no overrides (`None`); one that exists but can't be
/// read is an error the report names, the same as one that doesn't parse.
fn read_text(path: &std::path::Path) -> Option<Result<String, String>> {
    match std::fs::read_to_string(path) {
        Ok(t) => Some(Ok(t)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
        Err(e) => Some(Err(e.to_string())),
    }
}

fn parse_overrides(text: &str) -> Result<Overrides, String> {
    let file: OverrideFile = toml::from_str(text).map_err(|e| {
        // The full error names the line and column; one line of it, so it
        // reads inside a sentence of the report's footer.
        e.to_string()
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
    })?;
    let mut models = BTreeMap::new();
    for (id, e) in file.models {
        let rates = [Some(e.input), Some(e.output), e.cache_read, e.cache_write];
        if rates.iter().flatten().any(|r| !r.is_finite() || *r < 0.0) {
            return Err(format!("{id}: prices must be non-negative numbers"));
        }
        let price = Price {
            input: e.input,
            output: e.output,
            cache_read: e.cache_read.unwrap_or(e.input),
            cache_write: e.cache_write.unwrap_or(e.input),
        };
        // `GPT-5.4` and `codex/gpt-5.4` are one id; two prices for it is a
        // conflict to report, not a coin to toss.
        if models.insert(canonical(&id), price).is_some() {
            return Err(format!("{id}: priced twice under the same id"));
        }
    }
    Ok(Overrides {
        models,
        error: None,
    })
}

/// Routing prefixes a provider sometimes writes in front of the model id
/// (Codex has logged `codex/gpt-5.4`). A fixed list: an unknown prefix
/// leaves the id unpriced rather than guessing what it routes to.
const PROVIDER_PREFIXES: &[&str] = &[
    "codex/",
    "anthropic/",
    "openai/",
    "gemini/",
    "google/",
    "xai/",
];

/// The id as the tables key it: lowercase, one known routing prefix off.
fn canonical(model: &str) -> String {
    let m = model.trim().to_ascii_lowercase();
    PROVIDER_PREFIXES
        .iter()
        .find_map(|p| m.strip_prefix(p))
        .map(str::to_string)
        .unwrap_or(m)
}

/// `id` without a trailing release date — `-20251001` or `-2025-10-01`,
/// exactly those shapes and only a plausible date (19xx/20xx, month 01–12,
/// day 01–31) — or `None` if it carries none. An eight-digit build number
/// is not a date and must not hand the id its base model's price.
fn undated(id: &str) -> Option<&str> {
    let date = |y: &str, m: &str, d: &str| {
        let num = |s: &str| {
            s.bytes()
                .all(|b| b.is_ascii_digit())
                .then(|| s.parse::<u32>().ok())
                .flatten()
        };
        y.len() == 4
            && m.len() == 2
            && d.len() == 2
            && matches!(num(y), Some(1900..=2099))
            && matches!(num(m), Some(1..=12))
            && matches!(num(d), Some(1..=31))
    };
    let (head, tail) = id.rsplit_once('-')?;
    if tail.len() == 8 && tail.is_ascii() && date(&tail[..4], &tail[4..6], &tail[6..]) {
        return Some(head);
    }
    // `-YYYY-MM-DD`: the split above took `DD`; peel `MM` and `YYYY` too.
    let (head, mm) = head.rsplit_once('-')?;
    let (head, yyyy) = head.rsplit_once('-')?;
    date(yyyy, mm, tail).then_some(head)
}

/// Exact lookup: the overrides first — the id as written, then without its
/// date — and only then the snapshot, the same two ways. A user who prices
/// `claude-haiku-4-5` means the dated ids a transcript carries too, even
/// where the snapshot happens to list a dated row of its own.
fn lookup(
    model: &str,
    overrides: &BTreeMap<String, Price>,
    snapshot: &BTreeMap<String, Price>,
) -> Option<Price> {
    let id = canonical(model);
    let base = undated(&id);
    let find = |table: &BTreeMap<String, Price>| {
        table
            .get(&id)
            .or_else(|| base.and_then(|b| table.get(b)))
            .copied()
    };
    find(overrides).or_else(|| find(snapshot))
}

fn price_for(model: &str) -> Option<Price> {
    lookup(model, &overrides().models, &SNAPSHOT.models)
}

/// Where the prices came from, for the line beside every cost figure:
/// the snapshot date and source commits, and the overrides file's state.
pub fn sources_note() -> String {
    let s = &*SNAPSHOT;
    let short = |sha: &str| sha.chars().take(7).collect::<String>();
    let mut note = format!(
        "API list prices as of {} (LiteLLM {}, models.dev {})",
        s.snapshot,
        short(&s.litellm),
        short(&s.models_dev)
    );
    let o = overrides();
    match &o.error {
        Some(e) => note.push_str(&format!("; {OVERRIDES_FILE} ignored: {e}")),
        None if !o.models.is_empty() => {
            note.push_str(&format!("; {} from {OVERRIDES_FILE}", o.models.len()))
        }
        None => {}
    }
    note
}

/// Models in `models` that carry usage but have no price — named in the
/// report so a partial figure says what it left out.
pub fn unpriced(models: &[(String, Totals)]) -> Vec<String> {
    models
        .iter()
        .filter(|(m, t)| t.sum() > 0 && price_for(m).is_none())
        .map(|(m, _)| m.clone())
        .collect()
}

fn cost_at(p: &Price, totals: &Totals) -> f64 {
    let per_m = |tokens: u64, rate: f64| tokens as f64 / 1_000_000.0 * rate;
    per_m(totals.input, p.input)
        + per_m(totals.output + totals.thinking, p.output)
        + per_m(totals.cache_read, p.cache_read)
        + per_m(totals.cache_write, p.cache_write)
}

/// API-equivalent list-price cost of `totals` under `model`'s rates —
/// `None` for an unknown model, so callers render `—` rather than `$0.00`
/// and a wrong number never masquerades as a free one.
pub fn cost_usd(model: &str, totals: &Totals) -> Option<f64> {
    price_for(model).map(|p| cost_at(&p, totals))
}

/// Cost of `totals` when its tokens span several models — the caller
/// supplies per-model totals (from `query::Stats::models` intersected by
/// provider or project). `None` if no model that carries usage has a
/// price — a priced model with no tokens must not turn "unknown" into
/// `$0.00` — and a mix prices the known share (documented behaviour:
/// partial estimates are still labelled as such).
pub fn cost_for_models(models: &[(String, Totals)]) -> Option<f64> {
    let has_usage = models.iter().any(|(_, t)| t.sum() > 0);
    let mut any = false;
    let mut sum = 0.0;
    for (m, t) in models {
        if let Some(c) = cost_usd(m, t) {
            sum += c;
            any |= t.sum() > 0 || !has_usage;
        }
    }
    any.then_some(sum)
}

/// Whether every model in `models` that carries any usage also has a
/// listed price — `false` means [`cost_for_models`]'s sum leaves out at
/// least one model's whole share, not merely a light one, so a caller
/// showing that sum as a headline figure should mark it partial.
pub fn fully_priced(models: &[(String, Totals)]) -> bool {
    unpriced(models).is_empty()
}

/// [`cost_for_models`] and [`fully_priced`] together — every caller that
/// shows a cost figure needs both (the number, and whether it left
/// anything out), so this is the one call site for that pair rather than
/// each caller re-deriving "is it partial" its own way. The second
/// element is only meaningful when the first is `Some`: a figure that
/// isn't shown at all has nothing to be partial about.
pub fn cost_summary(models: &[(String, Totals)]) -> (Option<f64>, bool) {
    let cost = cost_for_models(models);
    let partial = cost.is_some() && !fully_priced(models);
    (cost, partial)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn mtok_each() -> Totals {
        Totals {
            input: 1_000_000,
            output: 1_000_000,
            cache_read: 1_000_000,
            cache_write: 1_000_000,
            thinking: 0,
            messages: 0,
        }
    }

    fn snap(id: &str) -> Price {
        *SNAPSHOT
            .models
            .get(id)
            .unwrap_or_else(|| panic!("{id} is not in assets/prices.json any more"))
    }

    /// Every model id a real history carried on 2026-11-05, and the
    /// snapshot row it must resolve to — or `None`, for ids no source
    /// publishes a price for. Several of the hits (`gpt-5.6-*`, `gpt-5.5`,
    /// `claude-opus-4-8`) once priced at a shorter id's row instead.
    #[test]
    fn every_live_model_id_resolves_exactly_or_not_at_all() {
        let cases: &[(&str, Option<&str>)] = &[
            ("claude-opus-5-5", Some("claude-opus-5-5")),
            ("claude-opus-5", Some("claude-opus-5")),
            ("claude-opus-4-8", Some("claude-opus-4-8")),
            ("claude-fable-5", Some("claude-fable-5")),
            ("claude-fable-5-1", Some("claude-fable-5-1")),
            ("claude-sonnet-5", Some("claude-sonnet-5")),
            ("claude-sonnet-5-5", Some("claude-sonnet-5-5")),
            ("claude-haiku-5-5", Some("claude-haiku-5-5")),
            (
                "claude-haiku-4-5-20251001",
                Some("claude-haiku-4-5-20251001"),
            ),
            ("gpt-5.6-sol", Some("gpt-5.6-sol")),
            ("gpt-5.6-terra", Some("gpt-5.6-terra")),
            ("gpt-5.6-luna", Some("gpt-5.6-luna")),
            ("gpt-5.5", Some("gpt-5.5")),
            ("gpt-5.4", Some("gpt-5.4")),
            ("gpt-5.4-mini", Some("gpt-5.4-mini")),
            ("codex/gpt-5.4", Some("gpt-5.4")),
            ("gpt-5.3-codex", Some("gpt-5.3-codex")),
            ("gpt-5.3-codex-spark", Some("gpt-5.3-codex-spark")),
            ("gpt-5.2", Some("gpt-5.2")),
            ("gpt-5.2-codex", Some("gpt-5.2-codex")),
            ("gpt-5.1-codex-max", Some("gpt-5.1-codex-max")),
            ("gpt-5.1-codex-mini", Some("gpt-5.1-codex-mini")),
            ("gpt-6-astra", Some("gpt-6-astra")),
            ("gpt-6.1-sol", Some("gpt-6.1-sol")),
            ("gemini-3.8-flash", Some("gemini-3.8-flash")),
            ("gemini-3.7-flash", Some("gemini-3.7-flash")),
            ("grok-4.5", Some("grok-4.5")),
            // Antigravity's variant labels and Codex's subscription-only
            // auto-review model: no source lists a price, and nothing
            // proves they bill as the id they resemble.
            ("gemini-3.8-flash-n", None),
            ("gemini-3.7-flash-control", None),
            ("codex-auto-review", None),
            ("unknown", None),
            ("<synthetic>", None),
        ];
        for (id, want) in cases {
            assert_eq!(price_for(id), want.map(snap), "{id}");
        }
    }

    #[test]
    fn known_model_prices_per_class() {
        let p = snap("claude-sonnet-5");
        let want = p.input + p.output + p.cache_read + p.cache_write;
        let c = cost_usd("claude-sonnet-5", &mtok_each()).unwrap();
        assert!((c - want).abs() < 1e-9, "c={c} want={want}");
    }

    #[test]
    fn thinking_bills_at_output_rate() {
        let t = Totals {
            thinking: 1_000_000,
            ..Totals::default()
        };
        assert_eq!(cost_usd("gpt-5.4", &t), Some(snap("gpt-5.4").output));
    }

    #[test]
    fn unknown_model_is_none_not_zero() {
        assert_eq!(cost_usd("madeup-9000", &Totals::default()), None);
    }

    #[test]
    fn a_longer_sibling_never_lends_its_price() {
        // The bug this module was rewritten for: a prefix match priced
        // these at the shorter id's row.
        assert_eq!(price_for("gpt-5.6-sol-preview"), None);
        assert_eq!(price_for("claude-opus-4-9"), None);
        assert_ne!(price_for("gpt-5.6-luna"), price_for("gpt-5"));
    }

    #[test]
    fn a_date_suffix_comes_off_only_in_its_exact_shapes() {
        assert_eq!(
            undated("claude-haiku-4-5-20251001"),
            Some("claude-haiku-4-5")
        );
        assert_eq!(undated("o3-mini-2025-01-31"), Some("o3-mini"));
        assert_eq!(undated("gpt-5.6-sol"), None);
        assert_eq!(undated("claude-opus-4-8"), None);
        assert_eq!(undated("model-2025-1-31"), None);
        assert_eq!(undated("model-202510011"), None);
        // An undated form the tables know is used; one they don't is not.
        let snapshot = BTreeMap::from([("claude-haiku-4-5".to_string(), snap("claude-haiku-4-5"))]);
        let none = BTreeMap::new();
        assert_eq!(
            lookup("claude-haiku-4-5-20991231", &none, &snapshot),
            Some(snap("claude-haiku-4-5"))
        );
        assert_eq!(lookup("claude-haiku-9-20991231", &none, &snapshot), None);
    }

    #[test]
    fn an_override_wins_and_can_price_an_unlisted_id() {
        let o = parse_overrides(
            r#"
[models."gemini-3.8-flash-n"]
input = 0.75
output = 3.75

[models."GPT-5.4"]
input = 1
output = 2
cache_read = 0.1
cache_write = 0
"#,
        )
        .unwrap();
        assert!(o.error.is_none());
        let s = &SNAPSHOT.models;
        let n = lookup("gemini-3.8-flash-n", &o.models, s).unwrap();
        // Cache rates left out default to input.
        assert_eq!((n.cache_read, n.cache_write), (0.75, 0.75));
        let g = lookup("codex/gpt-5.4", &o.models, s).unwrap();
        assert_eq!(
            (g.input, g.output, g.cache_read, g.cache_write),
            (1.0, 2.0, 0.1, 0.0)
        );
    }

    #[test]
    fn a_bad_override_file_is_refused_whole_with_a_reason() {
        for bad in [
            "[models.x]\ninput = 1\n",
            "[models.x]\ninput = 1\noutput = -2\n",
            "[models.x]\ninput = 1\noutput = 2\ncache = 3\n",
            "not toml at all",
        ] {
            assert!(parse_overrides(bad).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn the_snapshot_parses_and_names_its_sources() {
        assert!(SNAPSHOT.models.len() > 100);
        let note = sources_note();
        assert!(
            note.starts_with(&format!("API list prices as of {}", SNAPSHOT.snapshot)),
            "{note}"
        );
        // Every key is already canonical, or exact lookup could never hit it.
        for k in SNAPSHOT.models.keys() {
            assert_eq!(&canonical(k), k);
        }
    }

    #[test]
    fn every_snapshot_rate_is_per_million_tokens() {
        // A per-token figure that missed its ×1e6 lands near 1e-6; a
        // per-1M figure multiplied again lands in the millions. The window
        // is two orders of magnitude wider than any list price seen (a
        // tenth of a cent to ten thousand dollars per 1M) so a real price
        // never trips it, and no cache read costs more than fresh input.
        for (id, p) in &SNAPSHOT.models {
            for r in [p.input, p.output] {
                assert!((0.001..10_000.0).contains(&r), "{id}: {r}");
            }
            assert!(
                (0.0..=p.input).contains(&p.cache_read),
                "{id}: cr {}",
                p.cache_read
            );
            assert!(
                p.cache_write >= 0.0 && p.cache_write < 10_000.0,
                "{id}: cw {}",
                p.cache_write
            );
        }
    }

    #[test]
    fn an_override_reaches_the_dated_ids_of_the_model_it_names() {
        let o = parse_overrides("[models.\"claude-haiku-4-5\"]\ninput = 9\noutput = 9\n").unwrap();
        // The snapshot lists this dated id as a row of its own; the
        // user's undated price must still win over it.
        assert!(SNAPSHOT.models.contains_key("claude-haiku-4-5-20251001"));
        let p = lookup("claude-haiku-4-5-20251001", &o.models, &SNAPSHOT.models).unwrap();
        assert_eq!(p.input, 9.0);
    }

    #[test]
    fn a_number_that_is_not_a_date_stays_on_the_id() {
        assert_eq!(undated("model-12345678"), None);
        assert_eq!(undated("model-20251340"), None);
        assert_eq!(undated("model-20250001"), None);
        assert_eq!(undated("model-2025-13-01"), None);
        assert_eq!(undated("model-2025-12-32"), None);
        assert_eq!(undated("model-20251231"), Some("model"));
    }

    #[test]
    fn one_id_priced_twice_refuses_the_file() {
        let e = parse_overrides(
            "[models.\"GPT-5.4\"]\ninput = 1\noutput = 2\n[models.\"codex/gpt-5.4\"]\ninput = 3\noutput = 4\n",
        );
        assert!(e.is_err());
    }

    #[test]
    fn a_priced_model_with_no_tokens_does_not_make_unknown_usage_free() {
        let some_usage = Totals {
            input: 100,
            ..Totals::default()
        };
        let mix = [
            ("gpt-5.4".to_string(), Totals::default()),
            ("gemini-3.8-flash-n".to_string(), some_usage),
        ];
        assert_eq!(cost_summary(&mix), (None, false));
        // With no usage anywhere, a priced model still says $0, not "—".
        assert_eq!(cost_for_models(&mix[..1]), Some(0.0));
    }

    #[test]
    fn fully_priced_flags_an_unpriced_model_in_the_mix() {
        let some_usage = Totals {
            input: 100,
            ..Totals::default()
        };
        let known = ("gpt-5.4".to_string(), some_usage);
        let unknown = ("gemini-3.8-flash-n".to_string(), some_usage);
        assert!(
            fully_priced(std::slice::from_ref(&known)),
            "every model with usage is priced"
        );
        assert!(
            !fully_priced(&[known.clone(), unknown.clone()]),
            "an unpriced model carrying usage must flag the mix as partial"
        );
        assert_eq!(
            unpriced(&[known.clone(), unknown]),
            vec!["gemini-3.8-flash-n"]
        );
        // A model with no usage at all doesn't matter either way.
        assert!(fully_priced(&[
            known,
            ("gemini-3.8-flash-n".to_string(), Totals::default())
        ]));
    }
}
